safe_snippet:
// https://github.com/MaikKlein/ash/issues/354:
// Zero-initialize the result to prevent read_exact from possibly
// reading uninitialized memory.
let mut result = vec![0u32; words];
x.read_exact(unsafe { slice::from_raw_parts_mut(result.as_mut_ptr() as *mut u8, words * 4) })?;

old_snippet:
// TODO(taiki-e): when the minimum supported Rust version is bumped to 1.36+,
// replace this with `mem::MaybeUninit`.
#[allow(deprecated)]
let mut data: Data = mem::uninitialized();
ptr::write(&mut data as *mut Data as *mut F, f);

safe_snippet:
let mut data: MaybeUninit<A> = MaybeUninit::uninit();
ptr::copy_nonoverlapping(
    slice.as_ptr(),
    data.as_mut_ptr() as *mut A::Item,
    len,
);
